"""Function check_valid_timestamp
    Check for the correct format of string timestamp
    with format <date>_<time>

    :param timestamp: A string timestamp (any format)
    :return bool: True if pattern follows <date>_<time>, otherwise False
    """
def check_valid_timestamp(timestamp: Any = None) -> object {
    ts_valid = False;
    if (timestamp != None) {
        ts = timestamp.split("_");
        if ((len(ts) == 2) and (len(ts[0]) == 6) and (len(ts[1]) == 4)) {
            ts_valid = True;
        }
    }
    return ts_valid;
}

"""This polynomial was chosen because all of its zeroes (-2, 4, 8) lie in
    the x-range we're looking at, so it is quite wiggly"""
def poly_func(X: Any) -> object {
    return (((X ** 3) - (10 * (X ** 2))) + (8 * X) + 64);
}

"""
	insert polynomial root data into an SQL database
	"""
def insert_row(order: int) -> str {
    params = ', '.join(
        ["root{}, iroot{}".format(`root, `root) for `root in range(order)]
    );
    inserts = ', '.join(["?, ?" for `root in range(order)]);
    query = "INSERT OR REPLACE INTO polynomials (id, {}) VALUES (?, {})".format(
        params, inserts
    );
    return query;
}

